INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (73,'hbrown','Himan',NULL,'Brown','http://leemichaelwithers.tripod.com/himan_then.jpg',NULL,'The famous squeaking door intro to RMT is a continuation of the creaking door found in an earlier series: Inner Sanctum.  Himan Brown was the force behind that series, too.<br>HB also played bit parts in some of the shows.\r<P>\r"Himan Brown produced and directed radio series for CBS and NBC during the 1930s and 1940s (The Thin Man, Flash Gordon, Inner Sanctum , and others).  His collection of radio transcription discs includes not only programs he produced or directed, but also others produced for CBS Radio. Titles in the collection include episodes from You Are There (also known as CBS Is There), Suspense, Mystery Theatre, CBS Radio Workshop, Backstage Wife, Mr. Chameleon,  Inspector Brooks, Young Widder Brown, Stella Dallas, and Inspector Hawkes and Son." UGA.',NULL,NULL,'http://leemichaelwithers.tripod.com/rmt_himanbio.htm',NULL,'mouse');
