INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (100,'gracematthews','Grace',NULL,'Matthews',NULL,NULL,'Grace Matthews starred as Margot Lane along side Bret Morrison from 1946 to 1949. During her 1948\rpregnancy The Shadow was moved out of the Mutual Longacre Theatre to avoid placing Margot Lane''s relationship with "man\rabout town" Lamont Cranston in a negative light. Matthews other radio appearances include roles in Big Sister, The\rBrighter Day, Hilltop House and CBS Mystery Theater.  (myweb.cableone.net)\r',NULL,NULL,NULL,NULL,'browncalumet');
