INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (120,'adabney','Augusta',NULL,'Dabney',NULL,NULL,'AD studied at the UC Berkeley Department of Theater starred in many radio and TV soap operas.  She also appears on broadway.  She was married to <a href=http://www.mousetrap.net/~mouse/cbsrmt/showperson.php?id=wprince>William Prince</a> and <a href=http://www.mousetrap.net/~mouse/cbsrmt/showperson.php?id=kmccarthy>Kevin McCarthy</a>,  presumably not at the same time.','1918-10-23',NULL,'http://www.tvtome.com/tvtome/servlet/PersonDetail/personid-10536',NULL,'mouse');
