INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (122,'hwarner','Hank',NULL,'Warner',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (123,'jorbach','Jerry',NULL,'Orbach',NULL,NULL,'Jerry was born in the Bronx. His father, Leon, was a former vaudevillian actor and his mother, Emily, was a radio\rsinger. His family moved frequently and eventually settled in Waukegan, Illinois where he went to high school. The\rconstant moving made him the new kid on the block and forced him to become "a chameleon" to blend in his new settings.\rHe studied drama at the University of Illinois and at Northwestern. He then went to study acting in New York and got\rconstant work in musicals. He slowly pushed to get acting roles in tv and movies, but was frequently overlooked because\rof his musical roots. (imdb.com)','1935-10-20',NULL,NULL,NULL,'browncalumet');
