INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (190,'bpeters','Brock',NULL,'Peters','http://wwwimage.cbs.com/specials/the_locket/bios/images/thelocket_bios_peters.jpg',NULL,'Born of African and West Indian parentage in New York City, Brock Peters set his sights on a show business career early on, at age ten. A product of NYC''s famed Music and Arts High School, Peters initially fielded more odd jobs than acting jobs as he worked his way up from Harlem poverty. Landing a stage role in "Porgy and Bess" in 1949, he quit physical education studies at CCNY and went on tour with the acclaimed musical. His film debut came in 1954''s "Carmen Jones", but he really began to make a name for himself# --having dropped his real name, George Fisher, in 1953# --in such films as "To Kill a Mockingbird" and "The L-Shaped Room". (Tom Weaver)','1927-07-02',NULL,'http://voices.fuzzy.com/actor.idc?actor_id=201',NULL,'mouse');
INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (191,'fsternhagen','Frances',NULL,'Sternhagen',NULL,NULL,'Raised in Washington, D.C., Frances Sternhagen taught acting, singing and dancing to school children before first\rperforming herself with the Arena Stage Group. Since that time, she has been seen in numerous Broadway show, has been\rnominated five times for a Tony Award and received one for "The Good Doctor". Other shows that she has appeared in\rinclude "Equus", "On Golden Pond", "Angel" and "You Can''t Take it With You". Ms. Sternhagen''s film debut was in Up the\rDown Staircase (1967). Since then her credits have included Fedora (1978), Starting Over (1979), Outland (1981) and\rCommunion (1989). She delighted Off-Broadway audiences for over two years with her feisty portrayal of the title\rcharacter in "Driving Miss Daisy" (imdb.com).','1930-01-13',NULL,NULL,NULL,'browncalumet');
INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (192,'tgrimes','Tammy',NULL,'Grimes','http://www.42ndstreetthemusical.com/images/gallery/tammy_grimes_the_original_dorothy_brock_on_broadway.gif',NULL,'Tammy Grimes was a regular actor on RMT, and narrated the later shows when E.G. Marshall''s health started to fail.  She also played roles on Broadway, including leading roles in Unsinkable Molly Brown and 42nd Street.\r<P>Triivia: TG is Amanda Plummer''s mother (Amanda was named after a character TG played onstage)!   More trivia: TG was offered the lead role in the TV show Bewitched but turned it down.','1934-01-30',NULL,NULL,NULL,'mouse');
