INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (195,'mhartley','Marriette',NULL,'Hartley','http://rmt.radio.shows.org/images/mhartley1.jpg',NULL,'Mariette Hartley was born Mary Loretta, a name she dislikes, in Weston, Connecticut. She was raised in accordance\rwith the principles espoused by her behavorial psychiatrist grandfather, John Watson, who believed that children should\rnever be held o','1940-06-21',NULL,NULL,NULL,'browncalumet');
