INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (217,'mseldes','Marian',NULL,'Seldes','http://ibs.theatermania.com/news/images/1876a.jpg\r',NULL,'From 1967 to 1991 was a faculty member of the Juilliard School of Drama, where her students included Kevin Kline, Patti LuPone, Kevin Spacey, and Laura Linney.\r\rEarned a 1967 Tony award as Best Featured Actress in Edward Albee''s A Delicate Balance", and has since appeared in Albee''s "Three Tall Women" and "The Play About the Baby".\r\rEarned Tony nominations for "Father''s Day" in 1971, "Deathtrap" in 1978, and "Ring Round the Moon" in 1999.\r\rEntered into the Guinness Book of World Records for appearing in "Deathtrap" from 1978 until late in 1982 without ever missing a single performance.\r" (IMDB).  She also has written an important book on stage acting.','1928-08-23',NULL,NULL,NULL,'mouse');
