INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (229,'astang','Arnold',NULL,'Stang','http://www.dougmacaulay.com/kingspud/photos/astang.jpg',NULL,'Small, slight, bespectacled with horn-rimmed glasses, bulgy eyes and a voice that was a sort of high-pitched nasally, gargly yodel, he was cast most often as impish, nerdy types... He is probably best remembered as the spokesman for Chunky candy bars in a series of very successful commercials in which he exclaimed in his yodelly voice, What a chunk of chocolate!"" (dougmacaulay.com)','1905-04-08',NULL,NULL,NULL,'mouse');
INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (230,'jgrimes','Jack',NULL,'Grimes','http://www.mousetrap.net/~mouse/images/otr/jgrimes.jpg',NULL,'Had lunch today with Jack Grimes and his terrific wife, Joan.\r<P>\rJust do a Google search on Jack Grimes and get a quick overview of\rthis amazingly lively, fair-minded, gracious and funny man.  A quiet\rbut impressive career in the world of ent','1905-04-09',NULL,NULL,NULL,'Ahab');
