INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (245,'eeric','Elspeth',NULL,'Eric',NULL,NULL,'Elspeth Eric was one of radio''s busiest actresses throughout the 1940s and 1950 and was heard on such radio drama series as GANGBUSTERS, MOLLEE MYSTERY THEATER, MURDER AT MIDNIGHT, and others usually playing gun molls and ladies with criminal intents. In the 1970s she wrote and was heard on many of Himan Brown''s CBS MYSTERY THEATER radio series. (imdb)  EE also wrote and consulted on TV''s Another World.\r\r','1905-04-01',NULL,NULL,NULL,'radiofan');
