INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (293,'ptripp','Paul',NULL,'Tripp',NULL,NULL,'Paul Tripp was born on NYC''s Lower East Side on February 20, 1911. Originally he wanted to be an actor and singer in\rgrand Operas. But he had to lower his sights and perform in comic operas at local functions instead. He went to college\rand studied ',NULL,NULL,NULL,NULL,'nlevin, browncalumet');
INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (294,'rdryden','Robert',NULL,'Dryden','http://rmt.radio.shows.org/images/bobdryden.jpg',NULL,'Robert Dryden was one of radio''s busiest and most versatile character actors throughout the 1940s and 1950s. He\rwas frequently heard on such classic radio shows as Gangbusters, The FBI In Peace And War, Studio One, The Ford\rTheater, Casey Crime Photographer, Mollee Mystery Theater and many other dramatic programs as well as on numerous soap\roperas. In the 1970s Dryden starred with Peg Lynch on Lynch''s Little Things In Life radio series and was a frequent\rperformer on Himan Brown''s CBS Radio Mystery Theater series.\r<P>\rDryden was a voice-over regular on the popular 1930s radio series Gangbusters that featured weekly\repisodes based actual crime incidents. Each program ended with various descriptions of wanted criminals, many of whom\rwere later arrested due to avid listener participation. (imdb.com)',NULL,NULL,NULL,NULL,'browncalumet');
