INSERT INTO `cast` (`cast_id`,`cast_id_name`,`first_name`,`middle_name`,`last_name`,`image_url`,`soundclip_url`,`bio`,`born_on`,`died_on`,`offsite_url`,`other_series`,`credit`) VALUES (322,'jbeck','Jackson',NULL,'Beck','http://rmt.radio.shows.org/images/jackson_beck.jpg',NULL,'Among his other accomplishments, this man is famous (but perhaps unknown by name) for that wonderfully modulated\rvoice of his with which he so dramatically introduced the ''Superman'' episodes on radio and TV during the 1940''s and\r50''s. JB''s personal quotes: "Faster than a speeding bullet...more powerful than a locomotive... able to leap tall\rbuildings in a single bound.... Look! Up in the sky! Is it a bird? Is it a plane? It''s SUPERMAN!" (imdb.com)','1912-07-23',NULL,'http://voices.fuzzy.com/actor.idc?actor_id=1698','Tom Corbett, Philo Vance, Superman','mouse, browncalumet');
