INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (126,'1974-08-01','The Hit Man',': A hit man has a change of heart after meeting the wife of his intended target.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (127,'1974-08-05','I Thought You Were Dead','An authoress begins to get phone calls from the husband and writing partner she killed out of professional jealousy. What does he want with her?',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (128,'1974-08-06','The Headstrong Corpse','Lord Berly of Moreland is dead. In life, he feared being buried alive, so he is left to lie in an open crypt until doctors are sure he is dead. While lying in state, somebody steals his body. Murder, mutilation, and corpse snatching take place in this 1874 gothic whodunit.',0);
