INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (133,'1974-08-14','Journey Into Terror','A chronic loser picks up an old typewriter at a pawn shop. Turns out the typewriter is the goose that lays the golden egg. But all that glitters is not gold; it could be blood. ',0);
