INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (141,'1974-08-29','Medium Rare','A ghost, bent on revenge, uses a fake medium to get revenge on a pair of fellow gamblers who took him for big money when he was alive. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (142,'1974-09-02','The Return Of Anatole Chevenic','A young, poor man is consistently brow beat and nagged by his rich uncle who continually taunts him with his money. In a fit of rage. he kills his uncle. His tangled web of lies comes unspun slowly and painfully.',0);
