INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (159,'1974-10-10','The Doll','A professor uses a voodoo doll to win the affection of the young woman of his desires. The young woman is his niece whom he helped raise.',0);
