INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (162,'1974-10-17','The Last Escape','An aging escape artist wants to attempt the escape that defied Houdini. His wife and her lover want to see that he doesn''t succeed. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (163,'1974-10-21','Mind Over Matthew','An older man marries a young woman whom he soon suspects might be a witch. He asks his doctor to help him investigate.',0);
