INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (168,'1974-10-31','The Demon Spirit','A man sacrifices his soul to possess the woman he loves and dies. His desire overpowers death and he takes possession of her. Her family tries to drive him out. ',0);
