INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (517,'1976-09-13','The Tell-Tale Corpse','The mother of a dead bank robber is visted by some of her son''s former cell mates. When they kill her, she refuses to stay dead.',0);
