INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (519,'1976-09-16','Dr. Peterson''s Pills','A Maine country doctor seems to have a miracle cure for every ailment in his mysterious pink pills. But his curative abilities came at a steep price that has just come due.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (520,'1976-09-17','To Whom It May Concern','A woman who mysteriously avoids death from a gunshot through the heart finds that she brings death to everyone she loves.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (521,'1976-09-20','A Very Dear Ghost Indeed','A man and his daughter, traveling through Ireland late in the 19th century, are waylaid by a washed out bridge to an old castle. There, they hear a tale from the resident about an unfortunate man who first sold his daughter, then his soul, for money. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (522,'1976-09-21','The Rainbow Man','A snake oil pedaler and part time con-artists uses his skills to help a young couple who want to marry and to expose a corrupt sheriff',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (523,'1976-09-23','Don''t Play With Matches','Fire Chief Cassarole is the toast of the town because fires are almost non-existent because of his prevention methods. But the citizens of his sleepy, little town don''t know about his "hobbies". ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (524,'1976-09-24','Queen Of The Deadly Night','A serf woman of the Dark Ages learns that she must travel to a foreign land and become their queen. Before she can be queen, she must pass a test.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (525,'1976-09-27','The Ghostly Private Eye','A 19th century "ghost buster" meets his match in a violent and aggressive poltergeist in an American mansion',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (526,'1976-09-28','One Girl In A Million','A celebrity business consultant of the future searches the galaxy for an exact duplicate of his long dead girlfriend. Meanwhile, he feels compelled to kill anybody with the same last name as the man who killed his girlfriend. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (527,'1976-09-30','Not For Sale','A woman inherits an antique store when her uncle is murdered. When she refuses to sell the shop to the man who inhabits the upstairs apartment above the shop, she runs into major trouble. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (528,'1976-10-01','The Clairvoyant','A clairvoyant forsees an unexpected love in the life of a young, British aristocrat on the eve of World War II. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (529,'1976-10-04','The Midas Touch','A con man swindles a bank president repeatedly in this farce set on the eve of the Great Depression. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (530,'1976-10-05','Private Stock','A police detective argues with the ghost of his dead wife as he is confronted with the fact that his daughter is guilty of murder. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (531,'1976-10-07','Pool Of Fear','A spoiled rich girl hires a convict to kill her step mother who she feels is trying to replace her mother. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (532,'1976-10-08','The Tortured Twins','A Broadway actor marries a costar who is about to star in her first major motion picture. But when he meets her more sophisticated twin sister, he decides that identical twins are not all that identical and decides to off his wife to possess his twin.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (533,'1976-10-11','My Wife Doesn''t Understand Me','A research scientist, unhappy with his marriage, finds solace in the arms of his new secretary. But she has more than love on her mind. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (534,'1976-10-12','The God Killer','A typist is accused of murdering the author for whom she works. She insists that the murderer was a character from a novel fighting for his survival. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (535,'1976-10-14','The Living Corpse','A young man of Philadelphia society begins behaving badly and irresponsibly toward his dying mother as he enters a scandulous affair with a woman nobody else can see.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (536,'1976-10-15','A Point In Time','Two hikers encounter a strange town in the mountains that is stuck in the 1920s. The inhabitants have a reason for their seclusion.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (537,'1976-10-18','Killer''s Appointment','A young woman takes the rap and goes to prison for her boyfriend who rips of his employer. When he abandons her while she is in prison, she plots her revenge',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (538,'1976-10-19','The Mission Of Atropos','A detective follows the clues left by a corrupt industrialist using an illegal and deadly chemical.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (539,'1976-10-21','To Hang By The Neck','A young woman travels to her a ranch for what she thinks will be her friend and boarding school roomate''s wedding. Turns out the friend hung herself the night before. Her friend''s mother implores her to find out what really happened.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (540,'1976-10-22','Somebody Help Me!','A cop who is so ugly he can''t get a date, kills women who turn him down.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (541,'1976-10-27','The Deathly White Man','A woman takes a job as caretaker to a rich woman and her husband in their remote castle. There, she and the son of the wealthy couple learn the family''s darkest secret.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (542,'1976-10-28','Absolute Zero','young woman returns to her home town only to miss her mother''s funeral by just a few hours. She is most disturbed when she finds out her mother''s grave has been robbed. She and a young doctor set out to find out who and why.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (543,'1976-10-29','The Unborn','An American encounters a woman several times through his life as he moves between occupations. She grows younger each time. He falls in love not knowing he tarries with the mistress of the Devil.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (544,'1976-10-30','Witches'' Sabbath','A man with murder in his heart, falls in with a coven of witches celebrating their holy day. They inspire him to murder.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (545,'1976-10-31','The Queen Of Cats','See "Willard" only with cats. An evil witch uses cats to prey on children in a small town. A lawyer and a local sheriff try to corner her.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (546,'1976-11-04','City Of The Dead','In the 1890s, two scientists descend to a depth of five miles in the Carribean and find a civilization of hostile, man=like creatures who attack them.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (547,'1976-11-05','The Secret Chamber','A real estate agent recounts the tale of how an old mansion became unhaunted.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (548,'1976-11-08','The Graveyard','A man mourns hard for his lost love who died after riding out into a rain storm to buy a new dress. He learns the truth about her in a hard way. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (549,'1976-11-09','The Colony','A couple are driving on a country road when they encounter a UFO. When they travel to the little town of Colony to report it, they find themselves in deep trouble with the law.',0);
