INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (567,'1976-12-17','A Quiet Evening At Home','A woman goes to a train station to meet her lover so they can leave their spouses. But when she witnesses a murder, her lover leaves her and she fears testifying because her husband will find out. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (568,'1976-12-20','Date Of Death','A hypocondriac''s fear is heightened when his doctor tells him he has an aortic aneurism. His anger rises when his doctor later denies everh having the conversation. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (569,'1976-12-21','The Lone Survivor','The lone survivor of a plane crash at sea cannot remember who he is. A police detective, an airline executive, and a doctor work to find out.',0);
