INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (571,'1976-12-25','The Magus','A young servant girl falls under the charms of a magus. She becomes entranced in his presence, forsaking her mother and would-be suitor. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (572,'1976-12-27','The Mark Of Cain','A gunslinger hires on to a ranch to enforce a rancher''s will. The rancher''s daughter falls in love with him, making her betrothed angry enough to challenge him to a gun battle. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (573,'1976-12-28','The Artist','A wealthy industrialist falls for a married knife throwing performer. He worries that her husband will find out and deliberately hit her with a knife.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (574,'1976-12-30','Your Move, Mr. Ellers','An insurance investigator looks into the theft of several diamonds and other jewels from a jeweler. Every character in the story is a chess fan. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (575,'1976-12-31','Tomorrow''s Murder','A stressed sales manager gets more stressed when he finds his tombstone in the cemetary with a date of death a year in the future.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (576,'1977-01-03','Whose Little Girl Are You?','In a pill-induced suicidal stupor, a star tennis player recounts the events of her life that led her into a deep depression.',0);
