INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (578,'1977-01-06','The Man From Ultra','A warlock walks a timind artist through a series of Walter Mitty type fantasies to save him from insanity.',0);
