INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (818,'1978-04-18','Uncle Louis','A police detective tries to bring down a mobster. In teh process, he falls in love with a witness. Meanwhile, the gangster learns a secret from his own past.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (819,'1978-04-20','The Avocado Jungle','A writer assists an aging actess in writing her autobiography. In the process, the actress divulges a deep secret that ends up on tape.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (820,'1978-04-21','Bet With Angels','A mild-mannered advertising executives starts getting gambling tips from his dead friend who was an addicted gambler. He soon catches gambling fever and gets himself into trouble. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (821,'1978-04-24','The Grandee of Terra Loco','A reporter travels to a small, south Texas town to do a story on the life and death of a legendary small town mayor. When he gets there, he finds a strange conspiracy that he is determined to unravel.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (822,'1978-04-25','International Dateline','A World War II pilot keeps his wife on one side of the international dateline and his paramour on the other. Trouble arises when one crosses into the other hemisphere. Meanwhile a malovent spirit pursues his soul.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (823,'1978-04-27','The Queen Of Palmyra','A private investigator investigates a woman who claims to be a prophet and the reincarnation of a Roman queen. A financier''s nephew thinks she is trying to swindle him.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (824,'1978-04-28','The House On Chimney Pot Lane','A woman inherits an antique store when her uncle is murdered. When she refuses to sell the shop to the man who inhabits the upstairs apartment above the shop, she runs into major trouble. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (825,'1978-05-01','A Drink With Dionysius','A petty thief and con artists accidently acquires an nuclear weapon. He looks to sell it.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (826,'1978-05-02','The Figure In The Moonlight','A strange engraving of a house reveals a figure acting out a long forgotten crime. When the couple who inherit the photo search for its meaning, they learn a friend''s family secret.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (827,'1978-05-04','Journey To Somewhere','A train full of lost souls heads for a small town --- each for his or her own reason --- all of them sad.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (828,'1978-05-05','Cool Killer Karl','A cold-hearted killer takes a family hostage while hiding from the cops. He is befriended by the mother. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (829,'1978-05-08','Death And Desire','Two retired circus performers start a fake medium routine. When the "ghost" dies, problems arise.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (830,'1978-05-09','Room 418','A man checks into a hotel where he killed his wife the night before. He encounters her spirit in the room.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (831,'1978-05-11','The Guilt Of The Innocent','A young and poor Russian falls under the influence of a master thief who works a seaport.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (832,'1978-05-12','The Secret Of Shen-Si','A college professor becomes worried when his wife unaccountably can recite a first hand account of the sinking of the Titantic. Turns out that she can recount a lot more.',0);
