INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (835,'1978-05-18','Time Out Of Mind','A college student is in a car accident. While unconscious, he travels back in time and takes the place of his uncle during World War II. He has a task to perform to help his father.',0);
