INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (838,'1978-05-23','Window To Oblivion','A World War II pilot disappears while on routine patrol over the Bermuda Triangle. Thirty years later, psychics put him in touch with his widow.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (839,'1978-05-25','The Spy And The Traitor','A fictionalized account of Benedict Arnold''s betrayal of West Point to the British.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (840,'1978-05-26','Arctic Encounter','A Russian plane and an American plane crash over the arctic Circle. The crews encounter an alien world.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (841,'1978-05-29','The Rich Ostrich','An amusing and intriguing farce about an cirucs ostrich that snatches and swallows a valuable diamond from an Arab diplomat.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (842,'1978-05-30','The Bittersweet Honeymoon','A newly-wed couple thinks themselves lucky when a cruise line screw-up puts them a luxury suite aboard a ship. But when their cabin is broken into by a nine-fingered man, they change their minds.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (843,'1978-06-01','The Silent Woman','AFter a woman is forced to marry a man befitting her social position, a woman falls into a 27 year long silence. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (844,'1978-06-02','Diamond Cut Diamond','While on holiday in Monte Carlo, a wealthy man is swindled by a man who claims to be a psychic.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (845,'1978-06-05','The Undying Heart','A gambler gambles away a bookie''s payoff and has to find a way to get it back. He decides to ice a rich aunt.',0);
