INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (850,'1978-06-14','Charlie, The Actor','an old flatfoot cop is assigned to guard the king of a small country while he visits the United States. He recognizes him as an imposter who is actually an actor who was convicted of murder.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (851,'1978-06-16','The Unholy Miracle','A couple finds out the daughter they adopted from Russia 20 years ago might actually be the product of a Soviet experiment.',0);
