INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (855,'1978-06-26','Lady Bluebeard','An insurance adjustor is asked to investigate how a woman has had the unfortunate luck to bury six husbands. He fears becoming her seventh victim',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (856,'1978-06-28','The Quadruple','A trapeze performer sells his soul in exchange for being able to perform the ultimate stunt',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (857,'1978-06-30','The Good Times Express','A salesman''s flight is diverted to due to a June snowstorm in Boston. He decides to hop a train and finds strange traveling companions going to even stranger destinations.',0);
