INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (859,'1978-07-05','My Kingdom For A Horse','The story of a gambler, his horse, and the conversations they have.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (860,'1978-07-07','The Four-Fifteen Express','A man encounters a former acquaintance on a train who had reportedly absconded with 75,000 Pounds Sterling. First, he is accused of being in cahoots with the man, and then dismissed as mistaken identity.',0);
