INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (863,'1978-07-13','The Village Of Fools','A farcical account of how a man is sent out into the world to find the village of Helm. When he arrives, he is appointed judge and is tasked with saving the moon. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (864,'1978-07-14','The Hanging Judge','A true tale of a criminal''s revenge upon his accuser and upon a judge who mistakenly let him go free.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (865,'1978-07-17','The Tell-Tale Scar','A reporter and a DA pursue a mobster who was supposed to be dead and buried. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (866,'1978-07-18','The Absent-Minded League','A French detective is called in by Scotland Yard to solve a silver counterfieting case.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (867,'1978-07-20','The Further You Go, The Less You Know','A guru with the unlikely name of "The Guru" convinces a small time con artist that the con is actually the reincarnation of Leonardo DaVinci and has him paint a new Mona Lisa. ',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (868,'1978-07-21','The Locked Trunk','A sister scorned plots revenge on her sister who married the man she loves. After she gets her revenge, she wants more and pays dearly for it.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (869,'1978-07-24','Close Shave','A con artist convinces a lonely millionaire to marry the "queen" of a non-existent South American country. the queen is actually his blackjack dealing girlfriend.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (870,'1978-07-25','The Stranger Inside','An aristocratic woman goes through a voyage of self discovery after the murder of her step-daughter. A police detective joins her on that voyage.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (871,'1978-07-27','The Cabinet Of The Unsolved','An amateur actor uses his skill to hustle wealthy poker players. He ends up dead on a train without a ticket. Scotland Yard receives a letter from the man involved in his death that recounts the murder.',0);
INSERT INTO `episodes` (`episode_id`,`episode_date`,`episode_name`,`episode_plot`,`genre_id`) VALUES (872,'1978-07-28','Double-Take','Two women who seem to have written the same novel find themselves living the plot.',0);
